insert into public.quiz_questions
  (type_contenu, slug, ordre, question_fr, question_en, choix_fr, choix_en, bonne_reponse, explication_fr, explication_en)
values
  ('mythe', 'mythe-mba-manga-ndzie-manga-beti', 1, $q$Selon la tradition rapportée par Bernadette Ngono, de qui descendraient les Ewondo et les Bënë ?$q$, $q$According to the tradition reported by Bernadette Ngono, who are the Ewondo and the Bënë descended from?$q$, $q$["De deux fils d'Essomba Nag Ba'ana", "De deux chasseurs venus du nord de la Sanaga", "De deux sœurs manguissa, Mba Manga et Ndzie Manga", "De deux épouses du chef Charles Atangana"]$q$::jsonb, $q$["Two sons of Essomba Nag Ba'ana", "Two hunters from north of the Sanaga", "Two Manguissa sisters, Mba Manga and Ndzie Manga", "Two wives of the chief Charles Atangana"]$q$::jsonb, 2, $q$Selon Ngono (2024), Mba Manga serait l'aïeule de trois grandes maisons ewondo, Ndzie Manga celle des Bënë, et leur brouille expliquerait les tensions entre les deux peuples.$q$, $q$According to Ngono (2024), Mba Manga is said to be the ancestress of three great Ewondo houses, Ndzie Manga that of the Bënë, and their quarrel to explain the tensions between the two peoples.$q$),
  ('mythe', 'mythe-mba-manga-ndzie-manga-beti', 2, $q$Selon Laburthe-Tolra, cité par Ngono, quel rôle les Manguissa jouent-ils envers les Ewondo et les Bënë ?$q$, $q$According to Laburthe-Tolra, quoted by Ngono, what role do the Manguissa play towards the Ewondo and the Bënë?$q$, $q$["Ils sont donneurs de femmes", "Ils gardent le passage de la Sanaga", "Ils forgent leurs armes de guerre", "Ils sont leurs chefs supérieurs"]$q$::jsonb, $q$["They are wife-givers", "They guard the Sanaga crossing", "They forge their weapons of war", "They are their paramount chiefs"]$q$::jsonb, 0, $q$Ayant donné des épouses aux Ewondo et aux Bënë, les Manguissa sont du côté des oncles maternels : la maison d'où sont venues les mères. Laburthe-Tolra, lui, dit seulement « peut-être ».$q$, $q$Having given wives to the Ewondo and the Bënë, the Manguissa stand on the side of the maternal uncles: the house the mothers came from. Laburthe-Tolra himself only says "perhaps".$q$),
  ('mythe', 'mythe-mba-manga-ndzie-manga-beti', 3, $q$Dans les Jaunde-Texte de 1919, que dit la formule ewondo abum da sur Omba Manga et Ndzie Manga ?$q$, $q$In the 1919 Jaunde-Texte, what does the Ewondo phrase abum da say about Omba Manga and Ndzie Manga?$q$, $q$["Qu'ils sont deux frères jumeaux", "Qu'ils sont nés le même jour au même lieu", "Qu'ils ont le même père, Manga-Mbolo", "Qu'ils sont du même ventre, sans dire leur sexe"]$q$::jsonb, $q$["That they are twin brothers", "That they were born on the same day and place", "That they have the same father, Manga-Mbolo", "That they are of the same womb, without stating their sex"]$q$::jsonb, 3, $q$Abum da veut dire « d'un seul ventre » : la formule dit la mère, pas le sexe. Le mot « frères » vient du traducteur allemand Heepe, que sa langue obligeait à choisir un genre.$q$, $q$Abum da means "of one womb": the phrase states the mother, not the sex. The word "brothers" comes from the German translator Heepe, whose language forced him to choose a gender.$q$),
  ('mythe', 'mythe-mba-manga-ndzie-manga-beti', 4, $q$Dans les Jaunde-Texte, par quel nom Atangana-Esomba appelle-t-il ses guerriers avant la bataille de Mvoleye ?$q$, $q$In the Jaunde-Texte, by what name does Atangana-Esomba call his warriors before the battle of Mvoleye?$q$, $q$["« Vous, fils de Nnë Bodo ! »", "« Vous, Omba Manga de l'est et de l'ouest ! »", "« Vous, hommes de Tsungi Mbala ! »", "« Vous, Ewondo de la vallée du Mfundi ! »"]$q$::jsonb, $q$["\"You, sons of Nnë Bodo!\"", "\"You, Omba Manga of the east and of the west!\"", "\"You, men of Tsungi Mbala!\"", "\"You, Ewondo of the Mfundi valley!\""]$q$::jsonb, 1, $q$Au moment du danger, le chef n'appelle pas ses hommes par le nom d'un homme mais par celui de l'aïeule. Ngono a recueilli ce cri sous une autre forme : « venus du nord ou du sud ».$q$, $q$At the moment of danger, the chief does not call his men by a man's name but by the ancestress's. Ngono collected this cry in another form: "come from the north or from the south".$q$),
  ('mythe', 'mythe-mba-manga-ndzie-manga-beti', 5, $q$D'après le mémoire de Ngomedzap, pourquoi les trois fils de Mbala Manga portent-ils le nom « Mbala » ?$q$, $q$According to the Ngomedzap dissertation, why do Mbala Manga's three sons bear the name "Mbala"?$q$, $q$["C'est le nom du village où ils sont nés", "C'est un titre réservé aux fils d'un chef", "C'est le nom de leur mère, pour les distinguer", "C'est le nom du devin qui les a bénis"]$q$::jsonb, $q$["It is the name of the village where they were born", "It is a title reserved for a chief's sons", "It is their mother's name, to tell them apart", "It is the name of the diviner who blessed them"]$q$::jsonb, 2, $q$Le nom de la mère servait à savoir quels fils d'un même père sont sortis du même ventre. Devenu nom de maison, il dure : on dit encore Mvog Atangana Mbala, Mvog Fouda Mbala à Yaoundé.$q$, $q$The mother's name showed which of a father's sons came from the same womb. Turned into a house name, it lasts: people in Yaoundé still say Mvog Atangana Mbala, Mvog Fouda Mbala.$q$);

commit;

